import * as THREE from 'three';

export function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export const clamp = (x, a, b) => Math.min(b, Math.max(a, x));
export function smoothstep(a, b, x) {
  const t = clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

// ---------------------------------------------------------------------------
// Loft: a tube with elliptical cross-sections swept along a polyline.
// Rings run along the path, each ring has (radial + 1) vertices (seam duplicated
// so the loft can carry UVs).
// ---------------------------------------------------------------------------

export function createLoftGeometry(rings, radial, colorFn) {
  const count = rings * (radial + 1);
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(count * 3), 3));
  geo.setAttribute('normal', new THREE.BufferAttribute(new Float32Array(count * 3), 3));
  const uv = new Float32Array(count * 2);
  for (let i = 0; i < rings; i++) {
    for (let j = 0; j <= radial; j++) {
      const k = i * (radial + 1) + j;
      uv[k * 2] = j / radial;
      uv[k * 2 + 1] = i / (rings - 1);
    }
  }
  geo.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
  if (colorFn) {
    const col = new Float32Array(count * 3);
    const c = new THREE.Color();
    for (let i = 0; i < rings; i++) {
      for (let j = 0; j <= radial; j++) {
        const th = (j / radial) * Math.PI * 2;
        colorFn(c, i / (rings - 1), Math.cos(th), Math.sin(th));
        const k = (i * (radial + 1) + j) * 3;
        col[k] = c.r; col[k + 1] = c.g; col[k + 2] = c.b;
      }
    }
    geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
  }
  const idx = [];
  for (let i = 0; i < rings - 1; i++) {
    for (let j = 0; j < radial; j++) {
      const a = i * (radial + 1) + j;
      const b = a + radial + 1;
      const c = a + 1;
      const d = b + 1;
      idx.push(a, b, c, b, d, c);
    }
  }
  geo.setIndex(idx);
  geo.userData.rings = rings;
  geo.userData.radial = radial;
  return geo;
}

const _t = new THREE.Vector3();
const _s = new THREE.Vector3();
const _u = new THREE.Vector3();
const _ps = new THREE.Vector3(1, 0, 0);
const _sec = { rx: 0, ry: 0, ox: 0, oy: 0 };

// path: array of Vector3 (length === rings); section(t, out) fills rx, ry, ox, oy.
export function updateLoft(geo, path, section, upRef) {
  const { rings, radial } = geo.userData;
  const pos = geo.attributes.position.array;
  _ps.set(1, 0, 0);
  let r0 = 0, r1 = 0;
  for (let i = 0; i < rings; i++) {
    const p = path[i];
    _t.subVectors(path[Math.min(rings - 1, i + 1)], path[Math.max(0, i - 1)]).normalize();
    _s.crossVectors(_t, upRef);
    if (_s.lengthSq() < 1e-10) _s.copy(_ps);
    else _s.normalize();
    _ps.copy(_s);
    _u.crossVectors(_s, _t).normalize();
    _sec.ox = 0; _sec.oy = 0;
    section(i / (rings - 1), _sec);
    if (i === 0) r0 = Math.max(_sec.rx, _sec.ry);
    if (i === rings - 1) r1 = Math.max(_sec.rx, _sec.ry);
    for (let j = 0; j <= radial; j++) {
      const th = (j / radial) * Math.PI * 2;
      const cx = _sec.ox + _sec.rx * Math.cos(th);
      const cy = _sec.oy + _sec.ry * Math.sin(th);
      const k = (i * (radial + 1) + j) * 3;
      pos[k] = p.x + _s.x * cx + _u.x * cy;
      pos[k + 1] = p.y + _s.y * cx + _u.y * cy;
      pos[k + 2] = p.z + _s.z * cx + _u.z * cy;
    }
  }
  geo.attributes.position.needsUpdate = true;
  geo.computeVertexNormals();
  const nrm = geo.attributes.normal.array;
  // weld the seam normals
  for (let i = 0; i < rings; i++) {
    const a = i * (radial + 1) * 3;
    const b = (i * (radial + 1) + radial) * 3;
    for (let c = 0; c < 3; c++) {
      const m = (nrm[a + c] + nrm[b + c]) * 0.5;
      nrm[a + c] = m; nrm[b + c] = m;
    }
  }
  // collapsed end rings get the path tangent as normal
  const capNormal = (ring, dir) => {
    _t.subVectors(path[ring === 0 ? 1 : rings - 1], path[ring === 0 ? 0 : rings - 2]).normalize().multiplyScalar(dir);
    for (let j = 0; j <= radial; j++) {
      const k = (ring * (radial + 1) + j) * 3;
      nrm[k] = _t.x; nrm[k + 1] = _t.y; nrm[k + 2] = _t.z;
    }
  };
  if (r0 < 1e-4) capNormal(0, -1);
  if (r1 < 1e-4) capNormal(rings - 1, 1);
  geo.attributes.normal.needsUpdate = true;
}

export function buildLoft(path, section, { radial = 16, upRef = new THREE.Vector3(0, 1, 0), colorFn } = {}) {
  const geo = createLoftGeometry(path.length, radial, colorFn);
  updateLoft(geo, path, section, upRef);
  geo.computeBoundingSphere();
  return geo;
}

// ---------------------------------------------------------------------------
// Feather: a cambered leaf strip. Base at the origin, tip at z = -1,
// max width 1 along x. Vertex colours give a pale shaft and fringe.
// ---------------------------------------------------------------------------
export function featherGeometry({ segs = 8, emarg = 0, shaft = 1.3, fringe = 1.12, base = 0.75 } = {}) {
  const pos = [];
  const col = [];
  const idx = [];
  for (let i = 0; i <= segs; i++) {
    const s = i / segs;
    let hw = 0.5 * (0.35 + 0.65 * Math.sin(Math.min(1, s * 1.7) * Math.PI * 0.5));
    hw *= Math.sqrt(Math.max(0, 1 - Math.pow(s, 5)));
    if (emarg) hw *= 1 - emarg * smoothstep(0.4, 0.7, s);
    const y = -0.06 * Math.sin(Math.PI * s);
    const z = -s;
    const shade = base + (1 - base) * smoothstep(0, 0.35, s);
    pos.push(-hw, y - 0.004, z, 0, y + 0.012, z, hw, y - 0.004, z);
    const e = shade * (s > 0.2 ? fringe : 1);
    const m = shade * shaft;
    col.push(e, e, e, m, m, m, e, e, e);
  }
  for (let i = 0; i < segs; i++) {
    const a = i * 3;
    for (let k = 0; k < 2; k++) {
      const v0 = a + k, v1 = a + k + 1, v2 = a + 3 + k, v3 = a + 4 + k;
      idx.push(v0, v2, v1, v1, v2, v3);
    }
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  geo.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  geo.setIndex(idx);
  geo.computeVertexNormals();
  return geo;
}

// Add per-vertex colours to any geometry from a function of its normal/position.
export function paintGeometry(geo, fn) {
  const n = geo.attributes.normal;
  const p = geo.attributes.position;
  const col = new Float32Array(p.count * 3);
  const c = new THREE.Color();
  const nv = new THREE.Vector3();
  const pv = new THREE.Vector3();
  for (let i = 0; i < p.count; i++) {
    nv.fromBufferAttribute(n, i);
    pv.fromBufferAttribute(p, i);
    fn(c, nv, pv);
    col[i * 3] = c.r; col[i * 3 + 1] = c.g; col[i * 3 + 2] = c.b;
  }
  geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
  return geo;
}

// Shared GLSL chunks. The sky function is used by the sky dome, by the ocean
// for reflections/fog, and (via PMREM) for image based lighting, so the whole
// scene agrees on one sunset.

export const NOISE_GLSL = /* glsl */ `
float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}
float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  float a = hash12(i);
  float b = hash12(i + vec2(1.0, 0.0));
  float c = hash12(i + vec2(0.0, 1.0));
  float d = hash12(i + vec2(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}
// value noise + analytic gradient (x: value, yz: d/dp)
vec3 vnoised(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  vec2 du = 6.0 * f * (1.0 - f);
  float a = hash12(i);
  float b = hash12(i + vec2(1.0, 0.0));
  float c = hash12(i + vec2(0.0, 1.0));
  float d = hash12(i + vec2(1.0, 1.0));
  float k = a - b - c + d;
  return vec3(a + (b - a) * u.x + (c - a) * u.y + k * u.x * u.y,
              du * (vec2(b - a, c - a) + k * u.yx));
}
const mat2 FBM_ROT = mat2(1.6, 1.2, -1.2, 1.6);
float fbm(vec2 p) {
  float s = 0.0, a = 0.5;
  for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = FBM_ROT * p; a *= 0.5; }
  return s;
}
float fbm3(vec2 p) {
  float s = 0.0, a = 0.5;
  for (int i = 0; i < 3; i++) { s += a * vnoise(p); p = FBM_ROT * p; a *= 0.5; }
  return s * 1.14;
}
`;

export const SKY_GLSL = /* glsl */ `
uniform vec3 uSunDir;
uniform vec3 uSunColor;
uniform vec3 uSkyZenith;
uniform vec3 uSkyMid;
uniform vec3 uSkyHorizon;
uniform vec3 uCloudLit;
uniform vec3 uCloudDark;
uniform float uTime;

vec3 skyColor(vec3 d, float disc) {
  float e = d.y;
  float eh = max(e, 0.0);
  float sd = max(dot(d, uSunDir), 0.0);
  vec3 col = mix(uSkyHorizon, uSkyMid, smoothstep(0.0, 0.2, eh));
  col = mix(col, uSkyZenith, smoothstep(0.12, 0.75, eh));
  // glow around the sun, hugging the horizon
  col += uSunColor * (0.16 * pow(sd, 3.0) + 0.32 * pow(sd, 18.0) + 0.9 * pow(sd, 160.0));
  col += uSunColor * 0.3 * pow(sd, 1.6) * exp(-eh * 9.0);
  float cl = 0.0;
  if (e > 0.004) {
    vec2 uv = d.xz / (e + 0.09);
    uv = uv * 0.5 + vec2(uTime * 0.006, 0.0);
    float n = fbm(uv * vec2(0.5, 1.8));
    float band = smoothstep(0.015, 0.09, e) * (1.0 - smoothstep(0.3, 0.75, e));
    cl = smoothstep(0.5, 0.78, n) * band;
    float edge = 1.0 - smoothstep(0.5, 0.8, n);
    float lit = clamp(0.12 + 0.95 * pow(sd, 4.0) + 0.35 * edge * pow(sd, 1.5), 0.0, 1.0);
    vec3 cc = mix(uCloudDark, uCloudLit, lit);
    cc += uSunColor * pow(sd, 20.0) * edge * 2.0;
    col = mix(col, cc, cl * 0.92);
  }
  // below the horizon (only visible past the far edge of the ocean)
  col = mix(col, uSkyHorizon * 0.9, smoothstep(0.0, -0.05, e));
  col += disc * uSunColor * 22.0 * smoothstep(0.99962, 0.99982, sd) * (1.0 - 0.8 * cl);
  return col;
}
`;

// Small travelling chop shared by the ocean vertex shader and the CPU (so the
// board and its wake ride the same bumps). p.x already includes the flow offset.
export const CHOP_GLSL = /* glsl */ `
float chop(vec3 p, float t) {
  return 0.07 * sin(dot(p.xz, vec2(0.55, 0.835)) * 0.95 + t * 1.6)
       + 0.05 * sin(dot(p.xz, vec2(-0.62, 0.785)) * 1.45 + p.y * 0.4 + t * 2.05)
       + 0.03 * sin(dot(p.xz, vec2(0.96, -0.28)) * 2.2 + p.y * 0.6 + t * 2.7);
}
`;

// The breaking wave, described in the frame that travels with the surfer.
//
// The wave crest runs along x. Its cross-section (z, y) is a Catmull-Rom curve
// through 16 control points. The control points morph along x through five
// "break stages": an unbroken shoulder ahead of the surfer, the steep pocket,
// the full barrel, the closing barrel and finally whitewater behind. Because
// the curve is parametric the lip can overhang and fold back into a tube.

import * as THREE from 'three';
import { smoothstep } from './geom.js';

export const WAVE_SCALE = 3.4;   // wave height in scene units (pelican ~1.2 tall)
export const SURF_SPEED = 7.0;   // surfer speed along the line, relative to the water
export const WAVE_SPEED = 2.2;   // shoreward speed of the wave
export const NPTS = 16;

// (z, y) per control point, in units of wave height. Index meaning:
// 0-3 back of wave, 4 crest, 5 lip top, 6 lip curve, 7 lip tip,
// 8-9 lip underside / tube ceiling, 10-12 face, 13 trough, 14-15 flat front.
const STAGES = [
  // 0: shoulder (unbroken)
  [[-7, 0], [-3.5, 0.04], [-1.8, 0.27], [-0.9, 0.56], [-0.35, 0.76], [0, 0.82], [0.18, 0.8], [0.32, 0.75],
    [0.42, 0.69], [0.52, 0.62], [0.62, 0.53], [0.76, 0.4], [1.0, 0.2], [1.5, 0.04], [2.8, 0], [7, 0]],
  // 1: pocket, lip starting to pitch
  [[-7, 0], [-3.5, 0.06], [-1.8, 0.35], [-0.8, 0.75], [-0.2, 1.0], [0.25, 1.05], [0.55, 0.98], [0.68, 0.86],
    [0.6, 0.8], [0.48, 0.76], [0.4, 0.66], [0.36, 0.45], [0.48, 0.18], [1.05, 0], [2.6, 0], [7, 0]],
  // 2: barrel
  [[-7, 0], [-3.5, 0.06], [-1.8, 0.36], [-0.8, 0.78], [-0.1, 1.05], [0.6, 1.0], [1.08, 0.66], [1.18, 0.28],
    [1.0, 0.5], [0.62, 0.86], [0.28, 0.76], [0.12, 0.5], [0.22, 0.2], [0.8, 0], [2.4, 0], [7, 0]],
  // 3: closing barrel / foam ball
  [[-7, 0], [-3.5, 0.05], [-1.8, 0.3], [-0.85, 0.62], [-0.15, 0.82], [0.5, 0.75], [1.1, 0.55], [1.6, 0.25],
    [1.45, 0.3], [1.2, 0.38], [0.95, 0.38], [0.9, 0.22], [1.3, 0.06], [2.2, 0], [3.2, 0], [7, 0]],
  // 4: whitewater
  [[-7, 0], [-3.5, 0.04], [-1.8, 0.2], [-0.9, 0.4], [-0.2, 0.55], [0.4, 0.58], [1.0, 0.5], [1.6, 0.36],
    [1.85, 0.3], [2.1, 0.22], [2.35, 0.15], [2.6, 0.1], [2.9, 0.05], [3.4, 0], [4.2, 0], [7, 0]],
];

export function stageAt(x) {
  return smoothstep(22, 5, x) + smoothstep(5, -3, x) + smoothstep(-3, -9, x) + smoothstep(-9, -16, x);
}

export function ampAt(x) {
  if (x > 14) return 1 - 0.82 * smoothstep(14, 110, x);
  if (x < -30) return 1 - 0.4 * smoothstep(-30, -160, x);
  return 1;
}

// the crest line bends gently towards the shore away from the peak
export function zoffAt(x) {
  return 12 * (1 - Math.exp(-(x * x) / 8000));
}

export function makePoints() {
  return Array.from({ length: NPTS }, () => [0, 0]);
}

export function profileAt(x, out) {
  const s = stageAt(x);
  const a = ampAt(x) * WAVE_SCALE;
  const zo = zoffAt(x);
  const i = Math.min(3, Math.floor(s));
  const f = s - i;
  const A = STAGES[i];
  const B = STAGES[i + 1];
  for (let k = 0; k < NPTS; k++) {
    out[k][0] = (A[k][0] + (B[k][0] - A[k][0]) * f) * a + zo;
    out[k][1] = (A[k][1] + (B[k][1] - A[k][1]) * f) * a;
  }
  return out;
}

// Centripetal Catmull-Rom (same formulation as THREE.CatmullRomCurve3)
const _p0 = [0, 0];
const _p3 = [0, 0];
function dist4(a, b) {
  const dx = a[0] - b[0], dy = a[1] - b[1];
  return Math.pow(dx * dx + dy * dy, 0.25);
}
export function crEval(pts, u, res) {
  const n = pts.length;
  let seg = Math.floor(u);
  if (seg > n - 2) seg = n - 2;
  if (seg < 0) seg = 0;
  const t = u - seg;
  const p1 = pts[seg];
  const p2 = pts[seg + 1];
  let p0, p3;
  if (seg > 0) p0 = pts[seg - 1];
  else { _p0[0] = 2 * p1[0] - p2[0]; _p0[1] = 2 * p1[1] - p2[1]; p0 = _p0; }
  if (seg + 2 < n) p3 = pts[seg + 2];
  else { _p3[0] = 2 * p2[0] - p1[0]; _p3[1] = 2 * p2[1] - p1[1]; p3 = _p3; }
  let d0 = dist4(p0, p1), d1 = dist4(p1, p2), d2 = dist4(p2, p3);
  if (d1 < 1e-4) d1 = 1;
  if (d0 < 1e-4) d0 = d1;
  if (d2 < 1e-4) d2 = d1;
  for (let c = 0; c < 2; c++) {
    let t1 = (p1[c] - p0[c]) / d0 - (p2[c] - p0[c]) / (d0 + d1) + (p2[c] - p1[c]) / d1;
    let t2 = (p2[c] - p1[c]) / d1 - (p3[c] - p1[c]) / (d1 + d2) + (p3[c] - p2[c]) / d2;
    t1 *= d1; t2 *= d1;
    const c0 = p1[c];
    const c2 = -3 * p1[c] + 3 * p2[c] - 2 * t1 - t2;
    const c3 = 2 * p1[c] - 2 * p2[c] + t1 + t2;
    const v = c0 + t1 * t + c2 * t * t + c3 * t * t * t;
    const dv = t1 + 2 * c2 * t + 3 * c3 * t * t;
    if (c === 0) { res.z = v; res.dz = dv; } else { res.y = v; res.dy = dv; }
  }
  return res;
}

const _pa = makePoints();
const _pb = makePoints();
const _ra = { z: 0, y: 0, dz: 0, dy: 0 };
const _rb = { z: 0, y: 0, dz: 0, dy: 0 };

export function makeSample() {
  return { pos: new THREE.Vector3(), normal: new THREE.Vector3(), tx: new THREE.Vector3(), tu: new THREE.Vector3(), stage: 0 };
}

// Surface point at line position x and profile parameter u (0..15).
export function surfaceSample(x, u, out) {
  const h = 0.04;
  profileAt(x, _pa);
  crEval(_pa, u, _ra);
  profileAt(x + h, _pb);
  crEval(_pb, u, _rb);
  out.pos.set(x, _ra.y, _ra.z);
  out.tu.set(0, _ra.dy, _ra.dz);
  out.tx.set(1, (_rb.y - _ra.y) / h, (_rb.z - _ra.z) / h);
  out.normal.crossVectors(out.tu, out.tx).normalize();
  out.stage = stageAt(x);
  return out;
}

// CPU twin of CHOP_GLSL
export function chopAt(x, y, z, t) {
  const px = x + SURF_SPEED * t;
  return 0.07 * Math.sin((px * 0.55 + z * 0.835) * 0.95 + t * 1.6)
    + 0.05 * Math.sin((px * -0.62 + z * 0.785) * 1.45 + y * 0.4 + t * 2.05)
    + 0.03 * Math.sin((px * 0.96 + z * -0.28) * 2.2 + y * 0.6 + t * 2.7);
}

// One continuous ocean mesh: the grid's rows follow the wave profile near the
// break and fan out to the horizon, its columns run along the wave line.

import * as THREE from 'three';
import { NOISE_GLSL, SKY_GLSL, CHOP_GLSL } from './shaders.js';
import { WAVE_SCALE, SURF_SPEED, WAVE_SPEED, NPTS, makePoints, profileAt, crEval, stageAt, ampAt, zoffAt } from './wave.js';
import { smoothstep } from './geom.js';

const FAR_BACK = [-1500, -900, -520, -300, -180, -110, -68, -42];
const FAR_FRONT = [36, 60, 110, 220];
// samples per profile segment (segment k joins control points k and k+1)
const SEG = [5, 6, 8, 9, 10, 12, 14, 14, 12, 10, 10, 10, 10, 12, 16];

function buildColumns() {
  const step = (x) => (x < -20 ? 0.22 + (-20 - x) * 0.07 : x > 28 ? 0.22 + (x - 28) * 0.07 : 0.22);
  const right = [];
  let x = 0;
  while (x < 1500) { right.push(x); x += step(x); }
  right.push(1500);
  const left = [];
  x = -step(0);
  while (x > -1500) { left.push(x); x -= step(x); }
  left.push(-1500);
  return left.reverse().concat(right);
}

const vertexShader = /* glsl */ `
uniform float uTime;
uniform float uFlowX;
attribute vec4 aSurf;   // stage, profile param, v (along-surface coord), amplitude
varying vec3 vWorld;
varying vec3 vNrm;
varying vec4 vSurf;
${NOISE_GLSL}
${CHOP_GLSL}
void main() {
  vec3 p = position;
  vec3 n = normal;
  float stage = aSurf.x;
  float rp = aSurf.y;
  vec3 pf = p + vec3(uFlowX * uTime, 0.0, 0.0);
  float h = chop(pf, uTime);
  float lip = exp(-pow((rp - 7.0) / 1.4, 2.0)) * smoothstep(1.0, 1.8, stage);
  h *= 1.0 - 0.75 * lip;
  // the throwing lip wobbles
  h += lip * (1.0 - smoothstep(2.6, 3.2, stage)) * 0.07 * sin(pf.x * 0.9 - uTime * 2.0 + rp * 1.3);
  // boiling whitewater
  float ww = smoothstep(2.3, 3.5, stage) * smoothstep(3.0, 5.0, rp) * (1.0 - smoothstep(12.5, 14.5, rp));
  vec2 wq = vec2(pf.x * 0.45, aSurf.z * 0.6);
  h += ww * ((vnoise(wq + vec2(0.0, uTime * 0.7)) - 0.4) * 0.6 + (vnoise(wq * 2.3 - vec2(uTime * 0.9, 0.0)) - 0.5) * 0.3);
  p += n * h;
  vec4 wp = modelMatrix * vec4(p, 1.0);
  vWorld = wp.xyz;
  vNrm = normalize(mat3(modelMatrix) * n);
  vSurf = aSurf;
  gl_Position = projectionMatrix * viewMatrix * wp;
}
`;

const fragmentShader = /* glsl */ `
uniform float uFlowX;
uniform float uFlowV;
uniform float uWaveScale;
uniform vec3 uDeep;
uniform vec3 uShallow;
uniform vec3 uFoam;
varying vec3 vWorld;
varying vec3 vNrm;
varying vec4 vSurf;
${NOISE_GLSL}
${SKY_GLSL}

#define RW(DX, DY, K, A, S) { vec2 d = normalize(vec2(DX, DY)); float f = clamp(2.0 - (K) * fd, 0.0, 1.0); g += d * ((A) * (K) * cos(dot(d, q) * (K) + t * (S))) * f; }

vec2 rippleGrad(vec2 q, float t, float dist) {
  vec2 g = vec2(0.0);
  float fd = dist / 140.0;
  RW( 0.10,  1.00, 0.18, 0.30, 0.55)
  RW( 0.62,  0.78, 0.9, 0.060, 1.30)
  RW(-0.70,  0.71, 1.7, 0.032, 1.90)
  RW( 0.95, -0.25, 2.9, 0.017, 2.50)
  RW( 0.15,  0.99, 4.6, 0.010, 3.10)
  RW(-0.45, -0.89, 7.1, 0.0065, 3.90)
  RW( 0.80,  0.55, 10.5, 0.0042, 4.70)
  RW(-0.92,  0.35, 15.0, 0.0028, 5.60)
  float fn = clamp(1.6 - dist / 50.0, 0.0, 1.0);
  g += vnoised(q * vec2(1.3, 1.6) + vec2(t * 0.35, -t * 0.2)).yz * 0.05 * fn;
  g += vnoised(q * vec2(3.1, 3.7) - vec2(t * 0.5, t * 0.4)).yz * 0.022 * fn;
  return g;
}

void main() {
  float stage = vSurf.x;
  float rp = vSurf.y;
  float v = vSurf.z;
  float amp = vSurf.w;
  vec3 toCam = cameraPosition - vWorld;
  float dist = length(toCam);
  vec3 V = toCam / dist;
  vec3 N = normalize(vNrm);
  vec2 q = vec2(vWorld.x + uFlowX * uTime, v + uFlowV * uTime);

  // regions of the breaking wave
  float lip = exp(-pow((rp - 6.9) / 1.15, 2.0)) * smoothstep(1.15, 1.9, stage) * (1.0 - smoothstep(3.0, 3.7, stage));
  float tip = exp(-pow((rp - 7.0) / 0.5, 2.0)) * smoothstep(1.3, 2.0, stage) * (1.0 - smoothstep(3.2, 3.8, stage));
  float ww = smoothstep(2.3, 3.5, stage) * smoothstep(3.6, 5.0, rp) * (1.0 - smoothstep(13.0, 15.0, rp));
  float barrel = smoothstep(1.3, 2.0, stage) * (1.0 - smoothstep(2.8, 3.4, stage))
               * smoothstep(8.6, 9.6, rp) * (1.0 - smoothstep(11.6, 12.6, rp));

  // ripple normal in the surface tangent frame
  vec3 T = normalize(vec3(1.0, 0.0, 0.0) - N * N.x);
  vec3 B = cross(T, N);
  vec2 g = rippleGrad(q, uTime, dist) * (1.0 + ww * 1.5) * (1.0 - 0.5 * tip);
  vec3 n = normalize(N - g.x * T - g.y * B);

  // water body with light leaking through the thin crest and lip
  float hN = clamp(vWorld.y / (uWaveScale * max(amp, 0.15)), 0.0, 1.3);
  float thin = clamp(smoothstep(0.25, 1.0, hN) * 0.75 + lip * 0.9, 0.0, 1.0);
  float backLit = pow(clamp(dot(-V, uSunDir), 0.0, 1.0), 2.5);
  float wrap = clamp(dot(N, uSunDir) * 0.5 + 0.5, 0.0, 1.0);
  vec3 body = uDeep * (0.6 + 0.6 * wrap);
  body += uShallow * uSunColor * thin * (0.22 + 1.5 * backLit);
  body *= 1.0 - 0.5 * barrel;

  vec3 R = reflect(-V, n);
  R.y = abs(R.y);
  float F = 0.02 + 0.98 * pow(1.0 - clamp(dot(n, V), 0.0, 1.0), 5.0);
  vec3 refl = skyColor(R, 0.0) * (1.0 - 0.7 * barrel);
  vec3 col = mix(body, refl, F);
  float sd = max(dot(R, uSunDir), 0.0);
  col += uSunColor * (pow(sd, 1200.0) * 70.0 + pow(sd, 120.0) * 1.4 + pow(sd, 12.0) * 0.05) * (1.0 - barrel) * (1.0 - tip);

  // foam
  vec2 fq = q * vec2(0.5, 0.8);
  float n1 = fbm(fq + vec2(0.0, uTime * 0.1));
  float n2 = fbm(fq * 2.6 + vec2(uTime * 0.13, 3.7));
  float fn = n1 * 0.62 + n2 * 0.38;
  float foam = 0.0;
  foam = max(foam, ww * smoothstep(0.66 - 0.5 * ww, 0.8 - 0.48 * ww, fn));
  foam = max(foam, lip * smoothstep(0.62 - 0.3 * lip, 0.75 - 0.25 * lip, fn));
  foam = max(foam, tip * smoothstep(0.2, 0.45, fn + 0.1));
  float crest = exp(-pow((rp - 5.2) / 0.8, 2.0)) * smoothstep(0.35, 0.9, stage) * (1.0 - smoothstep(1.2, 1.6, stage));
  foam = max(foam, crest * 0.7 * smoothstep(0.6, 0.72, fn));
  float sn = fbm3(vec2(q.x * 1.4, q.y * 0.22) + vec2(0.0, uTime * 0.05));
  float face = smoothstep(10.2, 11.2, rp) * (1.0 - smoothstep(12.6, 13.5, rp))
             * smoothstep(0.5, 1.2, stage) * (1.0 - smoothstep(2.6, 3.2, stage));
  foam = max(foam, face * 0.75 * smoothstep(0.62, 0.74, sn));
  float lace = fbm3(q * vec2(0.16, 0.26) + 11.0);
  float front = smoothstep(12.8, 14.2, rp) * (0.55 + 0.45 * smoothstep(2.4, 3.8, stage));
  float backS = 1.0 - smoothstep(2.0, 3.6, rp);
  float patchy = smoothstep(0.56, 0.68, lace * 0.55 + n2 * 0.55);
  foam = max(foam, (front * 0.85 + backS * 0.35) * patchy);
  foam *= 1.0 - 0.6 * smoothstep(120.0, 600.0, dist);
  float bub = 0.8 + 0.2 * vnoise(q * 9.0);
  vec3 foamCol = uFoam * (0.5 + 0.5 * clamp(dot(n, uSunDir) * 0.5 + 0.5, 0.0, 1.0)) * bub;
  foamCol *= 1.0 - 0.45 * barrel;
  foamCol += uSunColor * uShallow * backLit * (lip + tip) * 0.8;
  col = mix(col, foamCol, clamp(foam, 0.0, 1.0));

  // aerial perspective towards the horizon
  vec3 hd = normalize(vec3(-V.x, 0.0005, -V.z));
  vec3 fogCol = skyColor(hd, 0.0);
  float fog = 1.0 - exp(-dist * 0.0028);
  fog = max(fog, smoothstep(600.0, 1400.0, dist));
  col = mix(col, fogCol, fog);

  gl_FragColor = vec4(col, 1.0);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

export function createOcean(shared) {
  const xs = buildColumns();
  const profRows = [];
  for (let k = 0; k < NPTS - 1; k++) {
    for (let s = 0; s < SEG[k]; s++) profRows.push(k + s / SEG[k]);
  }
  profRows.push(NPTS - 1);
  const nb = FAR_BACK.length;
  const np = profRows.length;
  const nr = nb + np + FAR_FRONT.length;
  const nc = xs.length;

  const pos = new Float32Array(nc * nr * 3);
  const surf = new Float32Array(nc * nr * 4);
  const pts = makePoints();
  const r = { z: 0, y: 0, dz: 0, dy: 0 };
  const py = new Float32Array(np);
  const pz = new Float32Array(np);
  const arc = new Float32Array(np);

  for (let i = 0; i < nc; i++) {
    const x = xs[i];
    profileAt(x, pts);
    const st = stageAt(x);
    const amp = ampAt(x);
    const zo = zoffAt(x);
    for (let j = 0; j < np; j++) {
      crEval(pts, profRows[j], r);
      py[j] = r.y;
      pz[j] = r.z;
      arc[j] = j === 0 ? 0 : arc[j - 1] + Math.hypot(r.y - py[j - 1], r.z - pz[j - 1]);
    }
    const total = arc[np - 1];
    const z0 = pts[0][0];
    const z1 = pts[NPTS - 1][0];
    const put = (row, y, z, rp, v) => {
      const k = row * nc + i;
      pos[k * 3] = x; pos[k * 3 + 1] = y; pos[k * 3 + 2] = z;
      surf[k * 4] = st; surf[k * 4 + 1] = rp; surf[k * 4 + 2] = v; surf[k * 4 + 3] = amp;
    };
    for (let j = 0; j < nb; j++) put(j, 0, FAR_BACK[j] + zo, -1, FAR_BACK[j] + zo);
    for (let j = 0; j < np; j++) {
      const u = profRows[j];
      // along-surface coordinate: measured from the back before the lip and
      // from the front after it, blended across the lip so flat water stays ~z
      const vBack = z0 + arc[j];
      const vFront = z1 - (total - arc[j]);
      const v = vBack + (vFront - vBack) * smoothstep(5, 9, u);
      put(nb + j, py[j], pz[j], u, v);
    }
    for (let j = 0; j < FAR_FRONT.length; j++) put(nb + np + j, 0, FAR_FRONT[j] + zo, 16, FAR_FRONT[j] + zo);
  }

  const index = new Uint32Array((nr - 1) * (nc - 1) * 6);
  let o = 0;
  for (let j = 0; j < nr - 1; j++) {
    for (let i = 0; i < nc - 1; i++) {
      const a = j * nc + i;
      const b = a + nc;
      const c = a + 1;
      const d = b + 1;
      index[o++] = a; index[o++] = b; index[o++] = c;
      index[o++] = b; index[o++] = d; index[o++] = c;
    }
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  geo.setAttribute('aSurf', new THREE.BufferAttribute(surf, 4));
  geo.setIndex(new THREE.BufferAttribute(index, 1));
  geo.computeVertexNormals();
  geo.computeBoundingSphere();

  const mat = new THREE.ShaderMaterial({
    uniforms: {
      ...shared,
      uFlowX: { value: SURF_SPEED },
      uFlowV: { value: WAVE_SPEED },
      uWaveScale: { value: WAVE_SCALE },
      uDeep: { value: new THREE.Color('#0b3a4a') },
      uShallow: { value: new THREE.Color('#3fd6b6') },
      uFoam: { value: new THREE.Color('#f4eee8') },
    },
    vertexShader,
    fragmentShader,
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.frustumCulled = false;
  return mesh;
}

import * as THREE from 'three';
import { NOISE_GLSL, SKY_GLSL } from './shaders.js';

export function createSky(shared) {
  const mat = new THREE.ShaderMaterial({
    uniforms: shared,
    vertexShader: /* glsl */ `
      varying vec3 vWorld;
      void main() {
        vec4 wp = modelMatrix * vec4(position, 1.0);
        vWorld = wp.xyz;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }
    `,
    fragmentShader: /* glsl */ `
      uniform float uDisc;
      varying vec3 vWorld;
      ${NOISE_GLSL}
      ${SKY_GLSL}
      void main() {
        vec3 d = normalize(vWorld - cameraPosition);
        gl_FragColor = vec4(skyColor(d, uDisc), 1.0);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }
    `,
    side: THREE.BackSide,
    depthWrite: false,
  });
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(2500, 64, 32), mat);
  mesh.frustumCulled = false;
  mesh.renderOrder = -10;
  return mesh;
}

// A low hazy headland on the horizon, off towards the setting sun.
export function createHeadland(color) {
  const R = 1450;
  const n = 90;
  const pos = [];
  const idx = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    const az = THREE.MathUtils.degToRad(-38 - 46 * t);
    const env = Math.pow(Math.sin(Math.PI * Math.pow(t, 0.7)), 0.8);
    const h = env * (30 + 22 * Math.sin(t * 17.0) * Math.sin(t * 5.3 + 1) + 9 * Math.sin(t * 41.0)) + 4;
    const x = Math.sin(az) * R;
    const z = -Math.cos(az) * R;
    pos.push(x, -20, z, x, Math.max(2, h), z);
    if (i < n) {
      const a = i * 2;
      idx.push(a, a + 2, a + 1, a + 1, a + 2, a + 3);
    }
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  geo.setIndex(idx);
  const mat = new THREE.MeshBasicMaterial({ color, fog: false, side: THREE.DoubleSide });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.renderOrder = -5;
  return mesh;
}

import * as THREE from 'three';
import { smoothstep } from './geom.js';

export const BOARD_LENGTH = 1.9;
const HALF_W = 0.28;
const THICK = 0.075;
const LIFT = 0.03; // raises the board so its belly sits at y = 0

function halfWidth(t) {
  if (t >= 0.45) return HALF_W * Math.pow(Math.max(0, 1 - Math.pow((t - 0.45) / 0.55, 2)), 0.5);
  return 0.11 + (HALF_W - 0.11) * Math.pow(Math.sin((t / 0.45) * Math.PI * 0.5), 0.8);
}
function rocker(t) {
  return t > 0.45 ? 0.13 * Math.pow((t - 0.45) / 0.55, 2.2) : 0.05 * Math.pow((0.45 - t) / 0.45, 2);
}
function thickness(t) {
  return THICK * Math.pow(Math.sin(Math.PI * t), 0.45);
}

// deck height (board-local y) at the stance
export const DECK_Y = LIFT + rocker(0.47) + thickness(0.47) * 0.62;

function deckTexture() {
  const c = document.createElement('canvas');
  c.width = 256;
  c.height = 1024;
  const g = c.getContext('2d');
  g.fillStyle = '#f4eee2';
  g.fillRect(0, 0, 256, 1024);
  // soft resin tint towards the rails
  const rail = g.createLinearGradient(0, 0, 256, 0);
  rail.addColorStop(0, 'rgba(214,190,150,0.55)');
  rail.addColorStop(0.18, 'rgba(214,190,150,0)');
  rail.addColorStop(0.82, 'rgba(214,190,150,0)');
  rail.addColorStop(1, 'rgba(214,190,150,0.55)');
  g.fillStyle = rail;
  g.fillRect(0, 0, 256, 1024);
  // nose stripes (canvas y = (1 - v) * 1024; v = 0 tail, 1 nose)
  const band = (v0, v1, col) => {
    g.fillStyle = col;
    g.fillRect(0, (1 - v1) * 1024, 256, (v1 - v0) * 1024);
  };
  band(0.7, 0.735, '#ff6a4d');
  band(0.745, 0.765, '#ffb347');
  band(0.775, 0.79, '#17a3a3');
  // retro sunset logo
  const cx = 128, cy = (1 - 0.36) * 1024, R = 74;
  g.save();
  g.beginPath();
  g.arc(cx, cy, R, 0, Math.PI * 2);
  g.clip();
  const grad = g.createLinearGradient(0, cy - R, 0, cy + R);
  grad.addColorStop(0, '#ffd166');
  grad.addColorStop(0.5, '#ff7a4d');
  grad.addColorStop(1, '#d6336c');
  g.fillStyle = grad;
  g.fillRect(cx - R, cy - R, 2 * R, 2 * R);
  g.fillStyle = '#f4eee2';
  for (let k = 0; k < 6; k++) {
    const y = cy + 6 + k * 12;
    g.fillRect(cx - R, y, 2 * R, 2 + k * 1.2);
  }
  g.restore();
  // stringer
  g.fillStyle = '#9a6a3a';
  g.fillRect(126.5, 0, 3, 1024);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  return tex;
}

function buildSurface(top) {
  const NL = 72;
  const NW = 22;
  const pos = [];
  const uv = [];
  const idx = [];
  for (let i = 0; i <= NL; i++) {
    const t = 0.5 - 0.5 * Math.cos((Math.PI * i) / NL);
    const z = (t - 0.5) * BOARD_LENGTH;
    const w = halfWidth(t);
    const r = rocker(t) + LIFT;
    const th = thickness(t);
    for (let j = 0; j <= NW; j++) {
      const s = -1 + (2 * j) / NW;
      const a = Math.abs(s);
      const y = top
        ? r + th * 0.62 * Math.pow(Math.max(0, 1 - a * a), 0.42)
        : r - th * 0.38 * Math.pow(Math.max(0, 1 - a * a * a), 0.3);
      pos.push(s * w, y, z);
      uv.push(j / NW, t);
    }
  }
  for (let i = 0; i < NL; i++) {
    for (let j = 0; j < NW; j++) {
      const a = i * (NW + 1) + j;
      const b = a + 1;
      const c = a + NW + 1;
      const d = c + 1;
      if (top) idx.push(a, c, b, b, c, d);
      else idx.push(a, b, c, b, d, c);
    }
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  geo.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  geo.setIndex(idx);
  geo.computeVertexNormals();
  return geo;
}

function finGeometry(scale) {
  const s = new THREE.Shape();
  s.moveTo(0, 0);
  s.quadraticCurveTo(0.02, 0.07, 0.085, 0.12);
  s.quadraticCurveTo(0.075, 0.05, 0.11, 0);
  s.lineTo(0, 0);
  const geo = new THREE.ExtrudeGeometry(s, { depth: 0.008, bevelEnabled: true, bevelThickness: 0.002, bevelSize: 0.002, bevelSegments: 1, curveSegments: 8 });
  geo.translate(-0.055, 0, -0.004);
  geo.scale(scale, scale, 1);
  return geo;
}

export function createSurfboard() {
  const group = new THREE.Group();
  const deckMat = new THREE.MeshPhysicalMaterial({ map: deckTexture(), roughness: 0.38, clearcoat: 0.8, clearcoatRoughness: 0.12 });
  const bottomMat = new THREE.MeshPhysicalMaterial({ color: '#1d8f8c', roughness: 0.35, clearcoat: 0.7, clearcoatRoughness: 0.15 });
  const finMat = new THREE.MeshStandardMaterial({ color: '#2b2b30', roughness: 0.4 });

  const deck = new THREE.Mesh(buildSurface(true), deckMat);
  const bottom = new THREE.Mesh(buildSurface(false), bottomMat);
  deck.castShadow = bottom.castShadow = true;
  deck.receiveShadow = true;
  group.add(deck, bottom);

  // thruster set; shape is drawn in the xy plane, rotated to hang under the tail
  const fins = [
    { t: 0.065, x: 0, toe: 0, cant: 0, s: 1.0 },
    { t: 0.15, x: 0.165, toe: -0.06, cant: -0.12, s: 0.9 },
    { t: 0.15, x: -0.165, toe: 0.06, cant: 0.12, s: 0.9 },
  ];
  for (const f of fins) {
    const fin = new THREE.Mesh(finGeometry(f.s), finMat);
    const z = (f.t - 0.5) * BOARD_LENGTH;
    const y = LIFT + rocker(f.t) - thickness(f.t) * 0.3;
    fin.position.set(f.x, y, z);
    // shape +x -> board -z (fin trails backwards), shape +y -> board -y (hangs down)
    fin.rotation.set(Math.PI, Math.PI * 0.5 + f.toe, 0, 'YXZ');
    fin.rotation.z = f.cant;
    fin.castShadow = true;
    group.add(fin);
  }
  return group;
}

export { smoothstep };

