// Non-interactive cinematography: a loop of shots around the surfer with slow
// glides between them.

import * as THREE from 'three';
import { clamp } from './geom.js';

const V3 = THREE.Vector3;

const SHOTS = [
  // front three-quarter, sunset over the lip
  { off: new V3(5.0, 1.0, 8.0), look: new V3(-1.4, 0.55, -0.8), fov: 40 },
  // down the line from the shoulder, looking into the tube
  { off: new V3(9.0, 1.4, 4.6), look: new V3(-3.2, 0.5, -0.6), fov: 38 },
  // low and close, almost at water level
  { off: new V3(2.4, -0.1, 4.4), look: new V3(-0.6, 0.65, -0.3), fov: 44 },
  // wide establishing shot
  { off: new V3(1.5, 5.0, 19.0), look: new V3(-4.5, 0.6, -2.0), fov: 42 },
];
const HOLD = 13;
const GLIDE = 5;

const smoother = (x) => x * x * x * (x * (x * 6 - 15) + 10);

export class CameraRig {
  constructor(camera) {
    this.camera = camera;
    this.follow = new V3(1, 1, 2);
    this.lookAt = new V3();
    this.off = new V3();
    this.lk = new V3();
    this.anchor = new V3(0.8, 1.0, 1.6);
    this.first = true;
  }

  update(t, dt, target) {
    const n = SHOTS.length;
    const tt = t % (n * HOLD);
    const i = Math.floor(tt / HOLD);
    const local = tt - i * HOLD;
    const f = smoother(clamp((local - (HOLD - GLIDE)) / GLIDE, 0, 1));
    const a = SHOTS[i];
    const b = SHOTS[(i + 1) % n];
    this.off.lerpVectors(a.off, b.off, f);
    this.lk.lerpVectors(a.look, b.look, f);
    const fov = a.fov + (b.fov - a.fov) * f;

    // slow drift so a held shot never feels frozen
    this.off.x += Math.sin(t * 0.21) * 0.7;
    this.off.y += Math.sin(t * 0.17 + 1) * 0.25;
    this.off.z += Math.cos(t * 0.13) * 0.7;

    const k = this.first ? 1 : 1 - Math.exp(-dt * 1.4);
    this.first = false;
    this.follow.lerp(target, k);
    const base = new V3().lerpVectors(this.follow, this.anchor, 0.35);

    const cam = this.camera;
    cam.position.copy(base).add(this.off);
    // handheld-ish float
    cam.position.x += Math.sin(t * 1.3) * 0.03 + Math.sin(t * 2.9) * 0.012;
    cam.position.y += Math.sin(t * 1.1 + 0.5) * 0.04 + Math.sin(t * 3.1) * 0.01;
    cam.position.y = Math.max(cam.position.y, 0.55);
    this.lookAt.copy(this.follow).add(this.lk);
    cam.lookAt(this.lookAt);
    if (Math.abs(cam.fov - fov) > 1e-3) {
      cam.fov = fov;
      cam.updateProjectionMatrix();
    }
  }
}

import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
import { ShaderPass } from 'three/addons/postprocessing/ShaderPass.js';

import { createSky, createHeadland } from './src/sky.js';
import { createOcean } from './src/ocean.js';
import { Surfer } from './src/surfer.js';
import { Spray } from './src/spray.js';
import { Trail } from './src/trail.js';
import { Flock } from './src/flock.js';
import { CameraRig } from './src/camera.js';

// ---------------------------------------------------------------- renderer
const renderer = new THREE.WebGLRenderer({ antialias: false, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 0.95;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFShadowMap;
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(40, window.innerWidth / window.innerHeight, 0.1, 6000);

// ---------------------------------------------------------------- sunset
const sunDir = new THREE.Vector3(-0.3, 0.17, -0.94).normalize();
const shared = {
  uTime: { value: 0 },
  uDisc: { value: 1 },
  uSunDir: { value: sunDir },
  uSunColor: { value: new THREE.Color('#ffc185').multiplyScalar(1.35) },
  uSkyZenith: { value: new THREE.Color('#2a3d78') },
  uSkyMid: { value: new THREE.Color('#d08a92') },
  uSkyHorizon: { value: new THREE.Color('#ffb27c') },
  uCloudLit: { value: new THREE.Color('#ffc49a') },
  uCloudDark: { value: new THREE.Color('#6e5b7e') },
};

const sky = createSky(shared);
scene.add(sky);

// image based lighting from the same sky (without the sun disc)
const pmrem = new THREE.PMREMGenerator(renderer);
const envScene = new THREE.Scene();
envScene.add(createSky(shared));
shared.uDisc.value = 0;
const envRT = pmrem.fromScene(envScene, 0, 0.1, 6000);
shared.uDisc.value = 1;
scene.environment = envRT.texture;
scene.environmentIntensity = 0.75;
pmrem.dispose();

scene.fog = new THREE.FogExp2(new THREE.Color('#e9a48a'), 0.0045);
scene.add(createHeadland(new THREE.Color('#8a6274')));

const sun = new THREE.DirectionalLight(new THREE.Color('#ffcf9e'), 2.8);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = -2.2;
sun.shadow.camera.right = 2.2;
sun.shadow.camera.top = 2.2;
sun.shadow.camera.bottom = -2.2;
sun.shadow.camera.near = 0.5;
sun.shadow.camera.far = 40;
sun.shadow.bias = -0.0004;
sun.shadow.normalBias = 0.015;
sun.shadow.radius = 3;
scene.add(sun, sun.target);

// cool fill from the open sky behind the camera
const fill = new THREE.DirectionalLight(new THREE.Color('#9fb6ff'), 0.9);
fill.position.set(0.3, 0.8, 1);
scene.add(fill);

// ---------------------------------------------------------------- world
const ocean = createOcean(shared);
scene.add(ocean);

const surfer = new Surfer();
scene.add(surfer.group);

const spray = new Spray(shared);
scene.add(spray.group);

const trail = new Trail(shared);
scene.add(trail.mesh);

const flock = new Flock();
scene.add(flock.group);

const rig = new CameraRig(camera);

// ---------------------------------------------------------------- post
const rt = new THREE.WebGLRenderTarget(1, 1, { type: THREE.HalfFloatType, samples: 4 });
const composer = new EffectComposer(renderer, rt);
composer.addPass(new RenderPass(scene, camera));
const bloom = new UnrealBloomPass(new THREE.Vector2(1, 1), 0.42, 0.55, 0.92);
composer.addPass(bloom);
composer.addPass(new OutputPass());
const grade = new ShaderPass({
  uniforms: { tDiffuse: { value: null }, uAspect: { value: 1 } },
  vertexShader: /* glsl */ `
    varying vec2 vUv;
    void main() { vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }
  `,
  fragmentShader: /* glsl */ `
    uniform sampler2D tDiffuse;
    uniform float uAspect;
    varying vec2 vUv;
    void main() {
      vec4 c = texture2D(tDiffuse, vUv);
      vec2 p = (vUv - 0.5) * vec2(uAspect, 1.0);
      float vig = smoothstep(1.15, 0.35, length(p));
      c.rgb *= mix(0.72, 1.0, vig);
      c.rgb = mix(c.rgb, c.rgb * vec3(1.03, 0.99, 0.95), 0.6);
      gl_FragColor = c;
    }
  `,
});
composer.addPass(grade);

function resize() {
  const w = window.innerWidth;
  const h = window.innerHeight;
  const pr = Math.min(window.devicePixelRatio, 2);
  renderer.setPixelRatio(pr);
  renderer.setSize(w, h);
  composer.setPixelRatio(pr);
  composer.setSize(w, h);
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  grade.uniforms.uAspect.value = w / h;
}
window.addEventListener('resize', resize);
resize();

// ---------------------------------------------------------------- loop
const params = new URLSearchParams(window.location.search);
let t = parseFloat(params.get('t') || '0') || 0;

function step(dt) {
  shared.uTime.value = t;
  surfer.update(t, dt);
  trail.update(t, dt, surfer);
  spray.update(t, dt, surfer);
  flock.update(t);
}

// pre-roll so spray and the carve line are already in the air on the first frame
{
  const t0 = t;
  t -= 3;
  for (let i = 0; i < 90; i++) { step(1 / 30); t += 1 / 30; }
  t = t0;
}

let last = performance.now();
function frame(now) {
  const dt = Math.min(0.05, Math.max(0, (now - last) / 1000));
  last = now;
  t += dt;
  step(dt);
  rig.update(t, dt, surfer.pos);
  sky.position.copy(camera.position);
  spray.setScale(renderer.domElement.height / (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov) / 2)));

  sun.target.position.copy(surfer.pos);
  sun.position.copy(surfer.pos).addScaledVector(sunDir, 20);
  fill.target.position.copy(surfer.pos);
  fill.position.copy(surfer.pos).add(new THREE.Vector3(0.3, 0.8, 1).multiplyScalar(10));

  composer.render();
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

